def _chapter(
	slug, title, summary, level, minutes, tags, topics, objectives, why,
	explanation, concepts, diagram, example, code, steps, mistakes, interviews,
	exercise, quiz, takeaways, references,
):
	return {
		"slug": slug,
		"title": title,
		"summary": summary,
		"level": level,
		"minutes": minutes,
		"tags": tags,
		"topics": topics,
		"objectives": objectives,
		"why": why,
		"explanation": explanation,
		"concepts": concepts,
		"diagram": diagram,
		"example": example,
		"code": code,
		"steps": steps,
		"mistakes": mistakes,
		"interviews": interviews,
		"exercise": exercise,
		"quiz": quiz,
		"takeaways": takeaways,
		"references": references,
	}


