def get_chapters():
	return CHAPTERS


def get_chapter(slug):
	return next((chapter for chapter in CHAPTERS if chapter["slug"] == slug), None)


def build_chapter_tutor_context(slug, question=""):
	chapter = get_chapter(slug)
	if chapter is None:
		return ""
	question_terms = {term.strip(".,?!:;()[]{}\"'").lower() for term in question.split()}
	concepts = chapter["topics"]
	relevant = [
		concept for concept in concepts
		if any(term in concept.lower() or concept.lower() in term for term in question_terms if len(term) > 3)
	]
	selected = relevant[:4] or concepts[:4]
	return (
		f"Learning Hub chapter: {chapter['title']} ({chapter['level']}). "
		f"Current focus: {', '.join(selected)}. "
		f"Chapter explanation: {chapter['explanation'][:900]} "
		"Teach from this selected chapter when relevant; answer unrelated questions normally."
	)[:1600]